import{_ as l,a0 as r,w as s,s as u,ao as p,I as n,x as a,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色 | LCTT x X-CMD","titleTemplate":false,"description":"GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive","title":"GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色","tag":"202204","desc":""},"relativePath":"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive.md","filePath":"[post].md"}'),d={name:"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive.md"};function m(b,t,w,g,f,T){const i=r("Link");return s(),u("div",null,[t[25]||(t[25]=p('<h1 id="gtk4-和-libadwaita-让-gnome-43-的文件管理器看起来很出色" tabindex="-1">GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色 <a class="header-anchor" href="#gtk4-和-libadwaita-让-gnome-43-的文件管理器看起来很出色" aria-label="Permalink to “GTK4 和 Libadwaita 让 GNOME 43 的文件管理器看起来很出色”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202204/07/163919x7t2hbblzmthmjfk.jpg" alt=""></p><blockquote><p>我们测试了 GNOME “<ruby>文件<rt>Files</rt></ruby>” v43 的开发版本，在这里将向你深入披露其外观、功能和性能的细节。</p></blockquote><p>GNOME <ruby>文件<rt>Files</rt></ruby>（以前的 Nautilus）也许是当今 GNOME 生态空间中使用最多的桌面应用。而且，自其首次发布以来，它从未接受过什么大修，而其他的 GNOME 应用乃至桌面本身都转移到了一个较新的技术栈。</p><p>现在一切都变了。GNOME 开发者正在为整个桌面和 “文件” 采用 GTK4 和 libadwaita。</p>',5)),n("p",null,[t[1]||(t[1]=a("GNOME “文件” v43 将在 2022 年晚些时候与 GNOME 43 一起发布，必将令人印象深刻。这个急需的 ",-1)),e(i,{href:"https://gitlab.gnome.org/GNOME/nautilus"},{default:o(()=>[...t[0]||(t[0]=[a("重制",-1)])]),_:1}),t[2]||(t[2]=a(" 带来了原生的深色模式、很棒的 UI 以及出色的 libadwaita 触控和 GTK4 性能提升。",-1))]),t[26]||(t[26]=p('<h3 id="gnome-文件-v43" tabindex="-1">GNOME “文件” v43 <a class="header-anchor" href="#gnome-文件-v43" aria-label="Permalink to “GNOME “文件” v43”">​</a></h3><p>我们安装了 GNOME “文件” v43 的 Flatpak 开发版本，下面是我们的发现。</p><p>第一印象，你应该注意到漂亮的 UI 触控，这要感谢 Libadwaita。关闭按钮是漂亮的圆形，而地址栏、选择高亮和整个文件窗口都有适当的间距和圆角。</p><p>所有的组件都没有出现边框高亮线。</p><p>下面是 v43（左）和 v42（右）的深浅模式的快速比较。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/GNOME-Files-43-and-42-Light-Mode-Comparison-1024x502.jpg" alt="GNOME Files 43 and 42 – Light Mode Comparison"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/GNOME-Files-43-and-42-Dark-Mode-Comparison-1024x493.jpg" alt="GNOME Files 43 and 42 – Dark Mode Comparison"></p><p>地址栏的文件夹分隔符保持不变。然而，字体却有了些许润色。地址栏的上下文菜单改变了，“<ruby>在终端打开<rt>Open in Terminal</rt></ruby>”选项没有了。取而代之的是 “<ruby>在其它应用中打开<rt>Open in Other application</rt></ruby>” 菜单。引入了一个新的选项 “<ruby>创建链接<rt>Create Link</rt></ruby>”。我想许多用户会怀念 “在终端打开” 的选项。</p><blockquote><p>3/3 更新（感谢 Rashid）：“在终端打开” 选项是 Nautilus 扩展包的一部分。因此，Flatpak 构建版不能“看到”它。因此，它本身并没有被删除。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/New-option-in-address-bar-menu-1024x267.jpg" alt="New option in address bar menu"></p><p>另一个重要的变化是你应该注意到两个主工具条菜单：a）视图按钮和 b）汉堡主菜单。这些上下文菜单项显示了菜单项及键盘快捷键。这也使它们看起来更显眼一些。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/The-Hamburger-menu-now-have-keyboard-shortcuts-1024x331.jpg" alt="The Hamburger menu now have keyboard shortcuts"></p><p>文件夹的上下文菜单现在有一个向上的小箭头，指向从它弹出的文件夹。文件夹的右键上下文菜单以组为单位组织得很好。例如，打开动作是分组的，而剪切、复制、粘贴在上下文菜单中以横杠的形式明显分开。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Context-Menu-for-folder-changes-1024x560.jpg" alt="Context Menu for folder changes"></p><p>我还注意到一个新的选项 “<ruby>粘贴到该文件夹<rt>Paste into the folder</rt></ruby>”，这个很好。</p><p>Nautilus 搜索几乎与 “文件” v42 相同，只是在 “文件” v43 中你可以通过创建日期/时间搜索。</p><p><s>然而，我注意到一个令人兴奋的变化。上下文菜单中的文件关联的应用名称被删除了。例如，如果你今天试图在 “文件” v42 中打开一个文本文件，它在上下文菜单中显示与之相关的应用名称。在 “文件” v43 中，它只显示 “打开”。我觉得这种改变是不必要的。之前的情况更好。</s></p><blockquote><p>3/3 更新（感谢 Rashid）：当我在试用 v43 的沙盒 Flatpak 版本时，它并没有看到系统关联。所以，这不是一个变化。但是，我又想知道，如果有人试图真正使用 Flatpak 版本怎么办。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/A-subtle-change-in-context-menu-for-file-association-1024x524.jpg" alt="A subtle change in context menu for file association"></p><p>所以，这就是我在这个应用的新 GTK4 版本中发现的整体变化。但它看起来不错？不是吗。此外，如果你是直接从 Ubuntu 20.04 LTS 来的，其中包含 “文件” 3.38，那么也许你的体验会是“哇”！如果你将 “文件” v43 与 “文件” v3.38 进行比较，大部分区域都发生了变化。对于这些用户来说，这将是一个相当不错的体验。</p><p>你应该记住，v43 仍在开发中，因此在未来最终发布时，可能会发生变化。</p><h3 id="愿望清单" tabindex="-1">愿望清单 <a class="header-anchor" href="#愿望清单" aria-label="Permalink to “愿望清单”">​</a></h3><p>如果比较各种 Linux 文件管理器，其他的文件管理器的选项远多于今天的 GNOME “文件”。</p><p>是这样的。</p><p>例如，Nemo 或 Dolphin - 这两个最好的文件管理器在各方面都胜过 “文件”。比较一下功能，GNOME “文件” 没有一些流行的功能：</p><ul><li>双面板或分割视图</li><li>从上下文菜单中打开一个根文件夹是困难的</li><li>一个用于文件夹浏览的向上箭头</li><li>没有从上下文菜单中创建一个新文件（文本、电子表格等）的选项</li><li>更多的排序和搜索功能</li></ul><p>我们希望这些功能能尽快出现在 GNOME “文件” 中。</p><h3 id="何时能用" tabindex="-1">何时能用 <a class="header-anchor" href="#何时能用" aria-label="Permalink to “何时能用”">​</a></h3><p>如上所述，这个版本的 GNOME “文件” 将与 GNOME 43 一起提供。因此，从 Linux 发行计划的角度来看，你应该在 2022 年 10 月的 Ubuntu 22.10 和今年晚些时候的 Fedora 37 上拥有它。</p>',29)),n("p",null,[t[6]||(t[6]=a("不幸的是，",-1)),e(i,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:o(()=>[...t[3]||(t[3]=[a("Ubuntu 22.04 LTS",-1)])]),_:1}),t[7]||(t[7]=a("（Jammy Jellyfish）和带有 ",-1)),e(i,{href:"https://www.debugpoint.com/2021/12/gnome-42/"},{default:o(()=>[...t[4]||(t[4]=[a("GNOME 42",-1)])]),_:1}),t[8]||(t[8]=a(" 的 ",-1)),e(i,{href:"https://www.debugpoint.com/2022/02/fedora-36/"},{default:o(()=>[...t[5]||(t[5]=[a("Fedora 36",-1)])]),_:1}),t[9]||(t[9]=a(" 将不会有 GNOME “文件” 43。主要原因是时间表不匹配，而且它是要移植到 GTK4 和彻底测试的复杂应用之一。然而，大部分上述的内部功能仍然会在 “文件” 42 中。但它可能缺少漂亮的 UI 变化和主题。",-1))]),t[27]||(t[27]=n("p",null,"尽管如此，我相信这个流行的文件管理器看起来不错，当它发布时，用户应该会很兴奋地使用它。让我知道你对 GNOME “文件” 43 的新变化的看法，请在下面的评论框中留言。",-1)),t[28]||(t[28]=n("p",null,"加油！",-1)),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[11]||(t[11]=a("via: ",-1)),e(i,{href:"https://www.debugpoint.com/2022/03/gnome-files-43/"},{default:o(()=>[...t[10]||(t[10]=[a("https://www.debugpoint.com/2022/03/gnome-files-43/",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=a("作者：",-1)),e(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[12]||(t[12]=[a("Arindam",-1)])]),_:1}),t[17]||(t[17]=a(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[13]||(t[13]=[a("lujun9972",-1)])]),_:1}),t[18]||(t[18]=a(" 译者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:o(()=>[...t[14]||(t[14]=[a("geekpi",-1)])]),_:1}),t[19]||(t[19]=a(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[15]||(t[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[20]||(t[20]=[a("LCTT",-1)])]),_:1}),t[23]||(t[23]=a(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:o(()=>[...t[21]||(t[21]=[a("Linux中国",-1)])]),_:1}),t[24]||(t[24]=a(" 荣誉推出",-1))])])}const O=l(d,[["render",m]]);export{M as __pageData,O as default};
